from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final[str] = "notes"


def _notes_base() -> Path:
    return (Path.cwd() / NOTES_DIR).resolve()


def safe_note_path(name: str) -> Path | None:
    """Return the resolved path of `name` inside NOTES_DIR, or None if it escapes.

    Rejects absolute paths, parent-directory components, NUL bytes, and any
    name whose resolved location (after following symlinks) is outside
    NOTES_DIR. Does not require the file to exist.
    """
    if "\x00" in name:
        return None
    if Path(name).is_absolute():
        return None
    base = _notes_base()
    try:
        candidate = (base / name).resolve()
    except (OSError, RuntimeError, ValueError):
        return None
    if not candidate.is_relative_to(base):
        return None
    return candidate


def read_note(name: str) -> str:
    """Return the contents of note `name` under NOTES_DIR.

    Returns "" when the name is unsafe (see safe_note_path), the file is
    missing, or the file cannot be read.
    """
    path = safe_note_path(name)
    if path is None:
        return ""
    try:
        return path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return ""


def is_readable_note(name: str) -> bool:
    """True when `name` is a regular file inside NOTES_DIR that can be read.

    Empty files count as readable. Missing, unsafe, directory, and
    unreadable names return False.
    """
    path = safe_note_path(name)
    if path is None:
        return False
    try:
        if not path.is_file():
            return False
        with path.open("rb") as fh:
            fh.read(0)
        return True
    except OSError:
        return False


def count_readable(names: list[str]) -> int:
    """Count how many entries of `names` are readable notes under NOTES_DIR.

    Relative to the current working directory. Untrusted names never cause
    a read outside NOTES_DIR.
    """
    return sum(1 for n in names if is_readable_note(n))


@pytest.fixture
def notes_cwd(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / NOTES_DIR
    notes.mkdir()
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "b.txt").write_text("", encoding="utf-8")
    (notes / "sub").mkdir()
    return tmp_path


def test_count_readable_counts_existing_files(notes_cwd: Path) -> None:
    assert count_readable(["a.txt", "b.txt"]) == 2


def test_count_readable_skips_missing(notes_cwd: Path) -> None:
    assert count_readable(["a.txt", "missing.txt"]) == 1


def test_count_readable_empty_list(notes_cwd: Path) -> None:
    assert count_readable([]) == 0


def test_count_readable_ignores_directories(notes_cwd: Path) -> None:
    assert count_readable(["sub"]) == 0


def test_count_readable_rejects_traversal(notes_cwd: Path) -> None:
    (notes_cwd / "secret.txt").write_text("nope", encoding="utf-8")
    assert count_readable(["../secret.txt"]) == 0


def test_count_readable_rejects_absolute_path(notes_cwd: Path) -> None:
    outside = notes_cwd / "outside.txt"
    outside.write_text("nope", encoding="utf-8")
    assert count_readable([str(outside)]) == 0


def test_count_readable_rejects_nul_byte(notes_cwd: Path) -> None:
    assert count_readable(["a.txt\x00.png"]) == 0


def test_count_readable_rejects_symlink_escape(notes_cwd: Path) -> None:
    target = notes_cwd / "secret.txt"
    target.write_text("nope", encoding="utf-8")
    (notes_cwd / NOTES_DIR / "link.txt").symlink_to(target)
    assert count_readable(["link.txt"]) == 0


def test_is_readable_note_true_for_empty_file(notes_cwd: Path) -> None:
    assert is_readable_note("b.txt") is True


def test_is_readable_note_false_for_missing(notes_cwd: Path) -> None:
    assert is_readable_note("nope.txt") is False


def test_is_readable_note_false_for_unsafe(notes_cwd: Path) -> None:
    assert is_readable_note("../../etc/passwd") is False


def test_safe_note_path_inside_notes(notes_cwd: Path) -> None:
    result = safe_note_path("a.txt")
    assert result is not None
    assert result.resolve() == (notes_cwd / NOTES_DIR / "a.txt").resolve()


def test_safe_note_path_rejects_escape(notes_cwd: Path) -> None:
    assert safe_note_path("../a.txt") is None


def test_read_note_returns_contents(notes_cwd: Path) -> None:
    assert read_note("a.txt") == "alpha"


def test_read_note_empty_for_missing(notes_cwd: Path) -> None:
    assert read_note("missing.txt") == ""


def test_read_note_empty_for_unsafe(notes_cwd: Path) -> None:
    (notes_cwd / "secret.txt").write_text("nope", encoding="utf-8")
    assert read_note("../secret.txt") == ""
